// Menerima payload dari wago-api webhook
// Format: { sessionId, event, data: { id, chat, sender, pushName, timestamp, body, type, ... } }
const req = $input.first().json;
const body = req.body ?? req;

let evt = body;
if (body.data) evt = body.data;

// Skip pesan dari diri sendiri dan group
if (evt.isFromMe === true || evt.isGroup === true) return [];

// Ambil pesan teks
const text = (evt.body || '').toString().trim();
if (!text) return [];

// Parsing format pendaftaran
// Contoh: Daftar Nama: Budi, Alamat: Jl. Mawar No. 1, No HP: 08123456789
const fields = {};
const lines = text.split(/[,\n]/);
for (const line of lines) {
  const kv = line.split(/[:=]/);
  if (kv.length >= 2) {
    const k = kv[0].trim().toLowerCase();
    const v = kv.slice(1).join(':').trim();
    fields[k] = v;
  }
}

// Fallback: deteksi field umum dari seluruh teks
const extract = (patterns) => {
  for (const p of patterns) {
    const m = text.match(new RegExp(p, 'i'));
    if (m) return m[1]?.trim();
  }
  return undefined;
};

const nama = fields['nama'] || fields['name'] || fields['nama lengkap'] || extract([r'Nama[:\s]+([^,\n]+)', r'Nama Lengkap[:\s]+([^,\n]+)']);
const alamat = fields['alamat'] || fields['address'] || extract([r'Alamat[:\s]+([^,\n]+)']);
const noHp = fields['no hp'] || fields['no. hp'] || fields['nomor hp'] || fields['phone'] || fields['hp'] || extract([r'(?:No\.?\s*HP|HP|Phone|Nomor)[:\s]+(\+?\d[\d\s\-]+)']);
const email = fields['email'] || fields['e-mail'] || extract([r'Email[:\s]+([^,\n\s]+)']);

// Normalisasi nomor HP ke format 62xxxx
let hpNorm = '';
if (noHp) {
  let digits = noHp.replace(/\D/g, '');
  if (digits.startsWith('0')) digits = '62' + digits.slice(1);
  if (!digits.startsWith('62')) digits = '62' + digits;
  hpNorm = digits;
}

return [{
  json: {
    nama: nama || evt.pushName || 'Tidak diketahui',
    alamat: alamat || '',
    no_hp: hpNorm || evt.sender?.replace(/@.*/,'') || '',
    email: email || '',
    pesan_asli: text,
    wa_sender: evt.sender || '',
    wa_chat: evt.chat || '',
    wa_pushName: evt.pushName || '',
    wa_timestamp: evt.timestamp || new Date().toISOString(),
    wa_messageId: evt.id || '',
    is_valid: !!(nama && hpNorm),
    registered_at: new Date().toISOString()
  }
}];
